python3 -c "
import json
from pathlib import Path
from collections import Counter

g = json.loads(Path('graphify-out/graph.json').read_text())
nodes = {n['id']: n for n in g['nodes']}

def under_internal(nid):
    n = nodes.get(nid)
    if not n: return False
    sf = n.get('source_file') or ''
    return sf.startswith('internal/')

CALL_RELS = {'calls','indirect_call'}
fanin = Counter()
for e in g['links']:
    if e.get('relation') in CALL_RELS:
        t = e['target']
        if under_internal(t):
            fanin[t] += 1

print('Top 15 fan-in (calls+indirect_call) among internal/ targets:')
for nid, c in fanin.most_common(15):
    n = nodes[nid]
    print(f'{c:4d}  {n.get(\"label\")}  [{n.get(\"type\")}]  {n.get(\"source_file\")}:{n.get(\"source_location\")}')

print()
print('--- calls only ---')
fanin2 = Counter()
for e in g['links']:
    if e.get('relation') == 'calls':
        t = e['target']
        if under_internal(t):
            fanin2[t] += 1
for nid, c in fanin2.most_common(10):
    n = nodes[nid]
    print(f'{c:4d}  {n.get(\"label\")}  {n.get(\"source_file\")}:{n.get(\"source_location\")}')
"
